<?php require __DIR__.'/layouts/admin_start.php'; ?><section class="module-panel"><h2>Fichier d’inventaire</h2><?php if($message): ?><div class="module-flash error"><?= htmlspecialchars($message) ?></div><?php endif; ?><div class="form-actions"><a class="header-btn secondary-btn" href="?modele=1">Télécharger le modèle CSV</a></div><table class="schema-table"><thead><tr><th>Colonne</th><th>Obligatoire</th><th>Exemple</th></tr></thead><tbody><tr><td>nom</td><td>Oui</td><td>Paracetamol 500 mg</td></tr><tr><td>quantite (stock physique)</td><td>Oui</td><td>20</td></tr><tr><td>prix (FCFA)</td><td>Non</td><td>500</td></tr></tbody></table><form method="POST" enctype="multipart/form-data"><?= csrfField() ?><input type="hidden" name="action" value="preview"><div class="fields"><div><label for="import_file">Fichier CSV ou Excel (.xlsx)</label><input id="import_file" type="file" name="import_file" accept=".csv,.xlsx" required></div></div><label class="check-row"><input type="checkbox" name="header" <?= $_SERVER['REQUEST_METHOD']!=='POST'||isset($_POST['header'])?'checked':'' ?>> Première ligne : en-tête</label><div class="form-actions"><button class="header-btn primary-btn">Afficher l’aperçu</button><a class="header-btn secondary-btn" href="/admin">Retour</a></div></form></section><?php if($preview): ?><section class="module-panel"><h2>Aperçu (<?= count($preview) ?> lignes)</h2><div class="preview-table"><table><thead><tr><th>Ligne</th><th>Médicament</th><th>Stock physique</th><th>Prix (FCFA)</th><th>Validation</th></tr></thead><tbody><?php foreach($preview as $d): ?><tr><td><?= $d['line'] ?></td><td><?= htmlspecialchars($d['nom'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8') ?></td><td><?= $d['quantite']===null?'—':(int)$d['quantite'] ?></td><td><?= htmlspecialchars($d['prix']??'—') ?></td><td class="<?= $d['error']?'invalid-row':'' ?>"><?= htmlspecialchars($d['error']?:'Valide') ?></td></tr><?php endforeach; ?></tbody></table></div><form method="POST"><?= csrfField() ?><input type="hidd